using System.Text;
using Agro360.Application.Contracts;
using Agro360.Domain.Fiscal;
using Agro360.Infrastructure.Persistence;
using Agro360.Multitenancy;
using Agro360.SharedKernel;
using Dapper;
using Npgsql;

namespace Agro360.Infrastructure.Services;

public sealed class FiscalService(DatabaseExecutor db, ITenantContext tenant, IFiscalStockIntegration stock, IFiscalFinancialIntegration financial, ILogger<FiscalService> logger) : IFiscalService
{
    public Task<dynamic> DashboardAsync(CancellationToken ct) => Tx(async (c,t) => await c.QuerySingleAsync(new CommandDefinition("""
        select count(*) filter(where i.status='DRAFT') invoice_drafts,count(*) filter(where i.status='UNDER_REVIEW') invoices_review,
        count(*) filter(where i.status in('AWAITING_DOCUMENT','DOCUMENT_PENDING')) documents_pending,
        coalesce(sum(i.total) filter(where i.status not in('DRAFT','CANCELLED') and i.confirmed_at>=date_trunc('month',now())),0) billed_month,
        (select count(*) from fiscal_documents d where d.tenant_id=@TenantId and d.status='REJECTED') documents_rejected,
        (select count(*) from fiscal_documents d where d.tenant_id=@TenantId and d.status='CANCELLED') documents_cancelled,
        (select count(*) from fiscal_documents d where d.tenant_id=@TenantId and d.status='EXTERNALLY_AUTHORIZED') documents_authorized,
        (select count(*) from fiscal_divergences d where d.tenant_id=@TenantId and d.status='OPEN') purchase_divergences,
        (select count(*) from fiscal_financial_integrations f where f.tenant_id=@TenantId and f.status in('PENDING','FAILED','NOT_CONFIGURED')) integration_pending
        from fiscal_invoice_drafts i where i.tenant_id=@TenantId and i.deleted_at is null
        """,new{tenant.TenantId},t,cancellationToken:ct)));

    public Task<IReadOnlyList<dynamic>> OperationsAsync(FiscalQuery q,CancellationToken ct)=>List("select * from fiscal_operations where tenant_id=@TenantId and deleted_at is null and (@Search is null or name ilike '%'||@Search||'%' or code ilike '%'||@Search||'%') and (@Status is null or case when active then 'ACTIVE' else 'INACTIVE' end=@Status) order by name limit @Take offset @Skip",q,ct);
    public Task<Guid> SaveOperationAsync(Guid? id,FiscalOperationCommand x,CancellationToken ct)=>Tx(async(c,t)=>{var key=id??Guid.CreateVersion7();var p=new DynamicParameters(x);p.Add("Id",key);p.Add("TenantId",tenant.TenantId);p.Add("UserId",tenant.UserId);var sql=id is null?"insert into fiscal_operations(id,tenant_id,code,name,type,purpose,suggested_cfop,moves_stock,generates_financial,requires_transport,requires_document,requires_cost_center,active,notes,created_by,updated_by) values(@Id,@TenantId,upper(@Code),@Name,@Type,@Purpose,@SuggestedCfop,@MovesStock,@GeneratesFinancial,@RequiresTransport,@RequiresDocument,@RequiresCostCenter,@Active,@Notes,@UserId,@UserId)":"update fiscal_operations set code=upper(@Code),name=@Name,type=@Type,purpose=@Purpose,suggested_cfop=@SuggestedCfop,moves_stock=@MovesStock,generates_financial=@GeneratesFinancial,requires_transport=@RequiresTransport,requires_document=@RequiresDocument,requires_cost_center=@RequiresCostCenter,active=@Active,notes=@Notes,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and deleted_at is null";if(await c.ExecuteAsync(new CommandDefinition(sql,p,t,cancellationToken:ct))==0)throw new NotFoundException("Operação fiscal",key);await Audit(c,t,"OPERATION",key,id is null?"CREATED":"UPDATED",ct);return key;});
    public Task<IReadOnlyList<dynamic>> RulesAsync(FiscalQuery q,CancellationToken ct)=>List("select r.*,o.name operation_name from fiscal_operation_rules r join fiscal_operations o on o.tenant_id=r.tenant_id and o.id=r.operation_id where r.tenant_id=@TenantId and r.deleted_at is null and (@Search is null or o.name ilike '%'||@Search||'%' or r.cfop ilike '%'||@Search||'%') and (@Status is null or case when r.active then 'ACTIVE' else 'INACTIVE' end=@Status) order by r.valid_from desc limit @Take offset @Skip",q,ct);
    public Task<Guid> SaveRuleAsync(Guid? id,FiscalRuleCommand x,CancellationToken ct){FiscalRules.ValidatePercentage(x.IcmsRate,x.PisRate,x.CofinsRate,x.IssRate,x.BaseReduction);if(x.ValidUntil<x.ValidFrom)throw new DomainException("Validade final anterior à inicial.","fiscal.validity_invalid");return Tx(async(c,t)=>{if(!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from fiscal_operations where tenant_id=@TenantId and id=@Id and active and deleted_at is null)",new{tenant.TenantId,Id=x.OperationId},t,cancellationToken:ct)))throw new DomainException("Operação fiscal inexistente ou inativa.","fiscal.operation_inactive");var conflict=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from fiscal_operation_rules where tenant_id=@TenantId and operation_id=@OperationId and origin_state=upper(@OriginState) and destination_state=upper(@DestinationState) and product_id is not distinct from @ProductId and category_id is not distinct from @CategoryId and active and id<>@Id and daterange(valid_from,coalesce(valid_until,'infinity'::date),'[]') && daterange(@ValidFrom,coalesce(@ValidUntil,'infinity'::date),'[]'))",new{tenant.TenantId,x.OperationId,x.OriginState,x.DestinationState,x.ProductId,x.CategoryId,Id=id??Guid.Empty,x.ValidFrom,x.ValidUntil},t,cancellationToken:ct));if(conflict)throw new DomainException("Existe regra conflitante; inative-a ou selecione explicitamente outra vigência.","fiscal.rule_conflict");var key=id??Guid.CreateVersion7();var p=new DynamicParameters(x);p.Add("Id",key);p.Add("TenantId",tenant.TenantId);p.Add("UserId",tenant.UserId);var sql=id is null?"insert into fiscal_operation_rules(id,tenant_id,operation_id,product_id,category_id,origin_state,destination_state,cfop,cst,csosn,icms_rate,pis_rate,cofins_rate,iss_rate,base_reduction,active,valid_from,valid_until,notes,created_by,updated_by) values(@Id,@TenantId,@OperationId,@ProductId,@CategoryId,upper(@OriginState),upper(@DestinationState),@Cfop,@Cst,@Csosn,@IcmsRate,@PisRate,@CofinsRate,@IssRate,@BaseReduction,@Active,@ValidFrom,@ValidUntil,@Notes,@UserId,@UserId)":"update fiscal_operation_rules set cfop=@Cfop,cst=@Cst,csosn=@Csosn,icms_rate=@IcmsRate,pis_rate=@PisRate,cofins_rate=@CofinsRate,iss_rate=@IssRate,base_reduction=@BaseReduction,active=@Active,valid_from=@ValidFrom,valid_until=@ValidUntil,notes=@Notes,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and deleted_at is null";if(await c.ExecuteAsync(new CommandDefinition(sql,p,t,cancellationToken:ct))==0)throw new NotFoundException("Regra fiscal",key);await Audit(c,t,"RULE",key,id is null?"CREATED":"UPDATED",ct);return key;});}
    public Task<IReadOnlyList<dynamic>> InvoicesAsync(FiscalQuery q,CancellationToken ct)=>List("select i.*,o.name operation_name,c.name customer_name from fiscal_invoice_drafts i join fiscal_operations o on o.tenant_id=i.tenant_id and o.id=i.operation_id join crm.customers c on c.tenant_id=i.tenant_id and c.id=i.customer_id where i.tenant_id=@TenantId and i.deleted_at is null and (@Search is null or i.internal_number ilike '%'||@Search||'%' or c.name ilike '%'||@Search||'%') and (@Status is null or i.status=@Status) order by i.created_at desc limit @Take offset @Skip",q,ct);
    public Task<Guid> CreateInvoiceAsync(FiscalInvoiceCommand x,CancellationToken ct){var total=FiscalRules.InvoiceTotal(x.Items.Select(i=>(i.Quantity,i.UnitPrice,i.Discount)),x.Freight,x.Insurance,x.OtherExpenses,x.Items.Sum(i=>i.InformedTaxes));if(x.Installments.Count>0&&x.Installments.Sum(i=>i.Amount)!=total)throw new DomainException("A soma das parcelas deve corresponder ao total.","fiscal.installments_total");return Tx(async(c,t)=>{var operation=await c.QuerySingleOrDefaultAsync<(bool Active,bool MovesStock,bool GeneratesFinancial,string Type)>(new CommandDefinition("select active,moves_stock,generates_financial,type from fiscal_operations where tenant_id=@TenantId and id=@Id and deleted_at is null",new{tenant.TenantId,Id=x.OperationId},t,cancellationToken:ct));if(!operation.Active)throw new DomainException("Operação fiscal inexistente ou inativa.","fiscal.operation_inactive");if(operation.Type=="EXPORT"&&x.ExportContractId is null)throw new DomainException("Exportação exige contrato internacional.","fiscal.export_contract_required");var id=Guid.CreateVersion7();var number=$"FAT-{DateTime.UtcNow:yyyyMMdd}-{id.ToString()[..8].ToUpperInvariant()}";await c.ExecuteAsync(new CommandDefinition("insert into fiscal_invoice_drafts(id,tenant_id,internal_number,customer_id,operation_id,sale_order_id,export_contract_id,payment_terms,carrier_id,delivery_address,freight,insurance,other_expenses,items_total,informed_taxes,total,status,notes,created_by,updated_by) values(@Id,@TenantId,@Number,@CustomerId,@OperationId,@SaleOrderId,@ExportContractId,@PaymentTerms,@CarrierId,@DeliveryAddress,@Freight,@Insurance,@OtherExpenses,@ItemsTotal,@Taxes,@Total,'DRAFT',@Notes,@UserId,@UserId)",new{Id=id,tenant.TenantId,Number=number,x.CustomerId,x.OperationId,x.SaleOrderId,x.ExportContractId,x.PaymentTerms,x.CarrierId,x.DeliveryAddress,x.Freight,x.Insurance,x.OtherExpenses,ItemsTotal=x.Items.Sum(i=>i.Quantity*i.UnitPrice-i.Discount),Taxes=x.Items.Sum(i=>i.InformedTaxes),Total=total,x.Notes,tenant.UserId},t,cancellationToken:ct));foreach(var i in x.Items)await c.ExecuteAsync(new CommandDefinition("insert into fiscal_invoice_items(id,tenant_id,invoice_id,product_id,lot_id,unit,quantity,unit_price,discount,informed_taxes,total,is_service,created_by,updated_by) values(@Id,@TenantId,@InvoiceId,@ProductId,@LotId,@Unit,@Quantity,@UnitPrice,@Discount,@InformedTaxes,@Total,@IsService,@UserId,@UserId)",new{Id=Guid.CreateVersion7(),tenant.TenantId,InvoiceId=id,i.ProductId,i.LotId,i.Unit,i.Quantity,i.UnitPrice,i.Discount,i.InformedTaxes,Total=i.Quantity*i.UnitPrice-i.Discount+i.InformedTaxes,i.IsService,tenant.UserId},t,cancellationToken:ct));foreach(var p in x.Installments)await c.ExecuteAsync(new CommandDefinition("insert into fiscal_invoice_installments(id,tenant_id,invoice_id,due_date,amount,created_by,updated_by) values(@Id,@TenantId,@InvoiceId,@DueDate,@Amount,@UserId,@UserId)",new{Id=Guid.CreateVersion7(),tenant.TenantId,InvoiceId=id,p.DueDate,p.Amount,tenant.UserId},t,cancellationToken:ct));return id;});}
    public async Task ConfirmInvoiceAsync(Guid id,CancellationToken ct){var flags=await Tx(async(c,t)=>await c.QuerySingleOrDefaultAsync<(bool MovesStock,bool GeneratesFinancial)>(new CommandDefinition("select o.moves_stock,o.generates_financial from fiscal_invoice_drafts i join fiscal_operations o on o.tenant_id=i.tenant_id and o.id=i.operation_id where i.tenant_id=@TenantId and i.id=@Id and i.status in('DRAFT','UNDER_REVIEW') and o.active",new{tenant.TenantId,Id=id},t,cancellationToken:ct)));try{if(flags.MovesStock)await stock.IntegrateInvoiceAsync(tenant.TenantId,id,ct);if(flags.GeneratesFinancial){var installments=await Tx(async(c,t)=>(IReadOnlyList<FiscalInstallmentCommand>)(await c.QueryAsync<FiscalInstallmentCommand>(new CommandDefinition("select due_date DueDate,amount Amount from fiscal_invoice_installments where tenant_id=@TenantId and invoice_id=@Id",new{tenant.TenantId,Id=id},t,cancellationToken:ct))).ToArray());await financial.CreateReceivablesAsync(tenant.TenantId,id,installments,ct);}await Tx(async(c,t)=>{if(await c.ExecuteAsync(new CommandDefinition("update fiscal_invoice_drafts set status='AWAITING_DOCUMENT',confirmed_at=now(),confirmed_by=@UserId,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and status in('DRAFT','UNDER_REVIEW')",new{tenant.TenantId,tenant.UserId,Id=id},t,cancellationToken:ct))==0)throw new DomainException("Faturamento não pode ser confirmado.","fiscal.confirm_invalid");});}catch(Exception ex){logger.LogError(ex,"Falha transacional ao integrar faturamento {InvoiceId} do tenant {TenantId}",id,tenant.TenantId);throw;}}
    public Task CancelInvoiceAsync(Guid id,string reason,CancellationToken ct){if(string.IsNullOrWhiteSpace(reason))throw new DomainException("Cancelamento exige motivo.","fiscal.cancel_reason_required");return Tx(async(c,t)=>{if(await c.ExecuteAsync(new CommandDefinition("update fiscal_invoice_drafts set status='CANCELLED',status_reason=@Reason,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and status not in('CANCELLED','CLOSED')",new{tenant.TenantId,tenant.UserId,Id=id,Reason=reason},t,cancellationToken:ct))==0)throw new DomainException("Faturamento não pode ser cancelado.","fiscal.cancel_invalid");});}
    public Task<IReadOnlyList<dynamic>> DocumentsAsync(FiscalQuery q,CancellationToken ct)=>List("select d.*,o.name operation_name from fiscal_documents d join fiscal_operations o on o.tenant_id=d.tenant_id and o.id=d.operation_id where d.tenant_id=@TenantId and d.deleted_at is null and (@Search is null or d.number ilike '%'||@Search||'%' or d.access_key=@Search) and (@Status is null or d.status=@Status) and (@Type is null or d.type=@Type) order by d.issued_at desc limit @Take offset @Skip",q,ct);
    public Task<Guid> CreateDocumentAsync(FiscalDocumentCommand x,CancellationToken ct){FiscalRules.ValidateAccessKey(x.AccessKey);if(x.Total<0)throw new DomainException("Total inválido.","fiscal.total_invalid");if(x.Type=="ENTRY"&&x.SupplierId is null)throw new DomainException("Documento de entrada exige fornecedor.","fiscal.supplier_required");return Tx(async(c,t)=>{var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into fiscal_documents(id,tenant_id,type,number,series,access_key,external_protocol,issued_at,customer_id,supplier_id,operation_id,status,total,document_reference,notes,created_by,updated_by) values(@Id,@TenantId,@Type,@Number,@Series,@AccessKey,@ExternalProtocol,@IssuedAt,@CustomerId,@SupplierId,@OperationId,'AWAITING_EXTERNAL_ISSUANCE',@Total,@DocumentReference,@Notes,@UserId,@UserId)",new{Id=id,tenant.TenantId,x.Type,x.Number,x.Series,x.AccessKey,x.ExternalProtocol,x.IssuedAt,x.CustomerId,x.SupplierId,x.OperationId,x.Total,x.DocumentReference,x.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"DOCUMENT",id,"CREATED",ct);return id;});}
    public Task ChangeDocumentStatusAsync(Guid id,string status,string reason,CancellationToken ct){if ((status is "REJECTED" or "CANCELLED") && string.IsNullOrWhiteSpace(reason))throw new DomainException("Documento rejeitado ou cancelado exige motivo.","fiscal.status_reason_required");return Tx(async(c,t)=>{if(await c.ExecuteAsync(new CommandDefinition("update fiscal_documents set status=@Status,status_reason=@Reason,authorized_at=case when @Status='EXTERNALLY_AUTHORIZED' then now() else authorized_at end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and deleted_at is null",new{tenant.TenantId,tenant.UserId,Id=id,Status=status,Reason=reason},t,cancellationToken:ct))==0)throw new NotFoundException("Documento fiscal",id);await Audit(c,t,"DOCUMENT",id,status,ct);});}
    public Task<Guid> CheckPurchaseAsync(FiscalPurchaseCheckCommand x,CancellationToken ct)=>Tx(async(c,t)=>{var different=x.ExpectedTotal!=x.ReceivedTotal;if(different&&string.IsNullOrWhiteSpace(x.Justification))throw new DomainException("Divergência de valor exige justificativa.","fiscal.divergence_justification");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into fiscal_purchase_checks(id,tenant_id,purchase_order_id,receipt_id,supplier_id,fiscal_document_id,expected_total,received_total,status,justification,created_by,updated_by) values(@Id,@TenantId,@PurchaseOrderId,@ReceiptId,@SupplierId,@FiscalDocumentId,@ExpectedTotal,@ReceivedTotal,@Status,@Justification,@UserId,@UserId)",new{Id=id,tenant.TenantId,x.PurchaseOrderId,x.ReceiptId,x.SupplierId,x.FiscalDocumentId,x.ExpectedTotal,x.ReceivedTotal,Status=different?"DIVERGENT":"APPROVED",x.Justification,tenant.UserId},t,cancellationToken:ct));if(different)await c.ExecuteAsync(new CommandDefinition("insert into fiscal_divergences(id,tenant_id,purchase_check_id,type,expected_value,received_value,status,justification,created_by,updated_by) values(@Id,@TenantId,@CheckId,'VALUE',@Expected,@Received,'OPEN',@Justification,@UserId,@UserId)",new{Id=Guid.CreateVersion7(),tenant.TenantId,CheckId=id,Expected=x.ExpectedTotal,Received=x.ReceivedTotal,x.Justification,tenant.UserId},t,cancellationToken:ct));else await financial.CreatePayablesAsync(tenant.TenantId,id,ct);return id;});
    public async Task<byte[]> ExportCsvAsync(string report,FiscalQuery q,CancellationToken ct){IReadOnlyList<dynamic> rows=report switch{"operations"=>await OperationsAsync(q,ct),"rules"=>await RulesAsync(q,ct),"invoices" or "invoices-customer" or "invoices-product" or "invoices-operation"=>await InvoicesAsync(q,ct),"documents" or "documents-status"=>await DocumentsAsync(q,ct),_=>await List("select * from fiscal_financial_integrations where tenant_id=@TenantId and (@Status is null or status=@Status) order by created_at desc limit @Take offset @Skip",q,ct)};var sb=new StringBuilder("sep=;\n");sb.AppendLine("Tipo;Identificador;Status;Valor");foreach(var r in rows)sb.AppendLine($"{Csv(report)};{Csv(Read(r,"internal_number")??Read(r,"number")??Read(r,"code"))};{Csv(Read(r,"status")??Read(r,"active"))};{Csv(Read(r,"total"))}");return Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(sb.ToString())).ToArray();}
    private Task<T> Tx<T>(Func<NpgsqlConnection,NpgsqlTransaction,Task<T>> work)=>db.InTenantTransactionAsync(work,CancellationToken.None);private Task Tx(Func<NpgsqlConnection,NpgsqlTransaction,Task> work)=>db.InTenantTransactionAsync(work,CancellationToken.None);
    private Task<IReadOnlyList<dynamic>> List(string sql,FiscalQuery q,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<dynamic>)(await c.QueryAsync(new CommandDefinition(sql,new{tenant.TenantId,q.Search,q.Status,q.Type,q.From,q.To,Take=Math.Clamp(q.PageSize,1,100),Skip=(Math.Max(q.Page,1)-1)*Math.Clamp(q.PageSize,1,100)},t,cancellationToken:ct))).ToArray());
    private Task Audit(System.Data.IDbConnection c,System.Data.IDbTransaction t,string entity,Guid id,string action,CancellationToken ct)=>c.ExecuteAsync(new CommandDefinition("insert into fiscal_document_events(id,tenant_id,entity_type,entity_id,event_type,created_by) values(@EventId,@TenantId,@Entity,@Id,@Action,@UserId)",new{EventId=Guid.CreateVersion7(),tenant.TenantId,Entity=entity,Id=id,Action=action,tenant.UserId},t,cancellationToken:ct));private static string Csv(object? value)=>$"\"{value?.ToString()?.Replace("\"","\"\"")}\"";private static object? Read(dynamic row,string name)=>((IDictionary<string,object>)row).TryGetValue(name,out var value)?value:null;
}

public sealed class FiscalIntegrationAdapter(DatabaseExecutor db,ITenantContext tenant) : IFiscalStockIntegration,IFiscalFinancialIntegration
{
 public Task IntegrateInvoiceAsync(Guid tenantId,Guid invoiceId,CancellationToken ct)=>db.InTenantTransactionAsync(async(c,t)=>{var blocked=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from fiscal_invoice_items i join storage.lots l on l.tenant_id=i.tenant_id and l.id=i.lot_id where i.tenant_id=@TenantId and i.invoice_id=@Id and not i.is_service and (l.status in('BLOCKED','REJECTED') or l.current_balance<i.quantity))",new{TenantId=tenantId,Id=invoiceId},t,cancellationToken:ct));if(blocked)throw new DomainException("Saldo insuficiente, lote bloqueado ou vencido.","fiscal.stock_blocked");await c.ExecuteAsync(new CommandDefinition("insert into fiscal_stock_movements(id,tenant_id,invoice_id,product_id,lot_id,type,quantity,status,created_by,updated_by) select gen_random_uuid(),tenant_id,invoice_id,product_id,lot_id,'SALE_OUT',quantity,'PENDING_EXTERNAL_STOCK',@UserId,@UserId from fiscal_invoice_items where tenant_id=@TenantId and invoice_id=@Id and not is_service",new{TenantId=tenantId,Id=invoiceId,tenant.UserId},t,cancellationToken:ct));},ct);
 public Task CreateReceivablesAsync(Guid tenantId,Guid invoiceId,IReadOnlyList<FiscalInstallmentCommand> installments,CancellationToken ct)=>Record(tenantId,"RECEIVABLE",invoiceId,ct);
 public Task CreatePayablesAsync(Guid tenantId,Guid purchaseCheckId,CancellationToken ct)=>Record(tenantId,"PAYABLE",purchaseCheckId,ct);
 private Task Record(Guid tenantId,string type,Guid reference,CancellationToken ct)=>db.InTenantTransactionAsync(async(c,t)=>{await c.ExecuteAsync(new CommandDefinition("insert into fiscal_financial_integrations(id,tenant_id,type,reference_id,status,message,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Type,@Reference,'PENDING','Aguardando processamento pelo módulo financeiro',@UserId,@UserId)",new{TenantId=tenantId,Type=type,Reference=reference,tenant.UserId},t,cancellationToken:ct));},ct);
}
